INSERT INTO "public"."payout_bank_codes" ("id", "method_key", "display_name", "category", "flutterwave_code", "is_verified", "notes", "created_at", "updated_at") VALUES
	('91a3e508-8379-42d0-8130-4711d2eae368', 'airtel', 'Airtel Money', 'mobile_money', 'ATL', false, 'Carried over from the pre-existing sweeper code, not from a confirmed Flutterwave source. Flutterwave''s public bank-list endpoint documents NG/GH/KE/UG/ZA/TZ only -- not ZM -- so this could not be looked up. Confirm with a real transfer, the Flutterwave dashboard, or Flutterwave support before trusting.', '2026-07-29 11:39:39.809807+00', '2026-07-29 11:39:39.809807+00'),
	('1dd43c9a-f3e0-4ee7-a413-3afee9eed64e', 'mtn', 'MTN Money', 'mobile_money', 'MTN', false, 'Same caveat as airtel. Plausible in form (Flutterwave uses short mnemonic codes elsewhere, e.g. "MPS" for Kenyan M-Pesa) but unverified for Zambia specifically.', '2026-07-29 11:39:39.809807+00', '2026-07-29 11:39:39.809807+00'),
	('c5633a8d-875d-4787-8312-a64d9687e2b1', 'zamtel', 'Zamtel Money', 'mobile_money', 'ZMT', false, 'Same caveat as airtel/mtn. Note: the shop payout form never actually offered "Zamtel" as a choice even though the sweeper already special-cased it -- added to the form alongside this migration.', '2026-07-29 11:39:39.809807+00', '2026-07-29 11:39:39.809807+00'),
	('934fbc73-e257-48cb-b4c9-f3673acfd85c', 'zanaco', 'Zanaco (Zambia National Commercial Bank)', 'bank', NULL, false, 'Bank name only -- no Flutterwave routing code confirmed.', '2026-07-29 11:39:39.809807+00', '2026-07-29 11:39:39.809807+00'),
